function nextRecDate(d,base,freq){var p=String(d).split('-').map(Number),bp=String(base||d).split('-').map(Number),step=freq==='quarter'?3:freq==='year'?12:1,day=bp[2]||p[2]||1,y=p[0],m=p[1]+step;while(m>12){m-=12;y++}var last=new Date(y,m,0).getDate();return y+'-'+String(m).padStart(2,'0')+'-'+String(Math.min(day,last)).padStart(2,'0')}
