function collectRecurringPending(){var now=today(),changed=false;(S.recurring||[]).forEach(function(r){if(!r.pending)r.pending=[];if(!r.active||!r.start)return;var cursor=r.next||r.start,guard=0;while(cursor<=now&&(!r.end||cursor<=r.end)&&guard++<240){var exists=S.exp.some(function(e){return e.recId===r.id&&e.d===cursor}),queued=r.pending.indexOf(cursor)>=0;if(!exists&&!queued){r.pending.push(cursor);changed=true}cursor=nextRecDate(cursor,r.start,r.freq)}if(!r.pending.length&&r.next!==cursor){r.next=cursor;changed=true}if(r.end&&cursor>r.end&&!r.pending.length&&r.active){r.active=false;changed=true}});return changed}
