function confirmRecurringPending(){var list=pendingRecurring(),made=0;list.forEach(function(x){if(!S.exp.some(function(e){return e.recId===x.r.id&&e.d===x.d})){S.exp.push({id:S.n++,t:x.r.title,c:x.r.cat,s:x.r.sub,a:x.a,d:x.d,recId:x.r.id});made++}x.r.pending=(x.r.pending||[]).filter(function(d){return d!==x.d});x.r.next=nextRecDate(x.d,x.r.start,x.r.freq)});if(made){lg('مصاريف متكررة','تسجيل '+made+' مصروف مستحق بعد التأكيد');save()}return made}
function confirmRecurringItem(id,date){var x=pendingRecurring().filter(function(v){return String(v.r.id)===String(id)&&v.d===date})[0];if(!x)return 0;var made=0;if(!S.exp.some(function(e){return e.recId===x.r.id&&e.d===x.d})){S.exp.push({id:S.n++,t:x.r.title,c:x.r.cat,s:x.r.sub,a:x.a,d:x.d,recId:x.r.id});made++}x.r.pending=(x.r.pending||[]).filter(function(d){return d!==x.d});x.r.next=nextRecDate(x.d,x.r.start,x.r.freq);if(made){lg('مصاريف متكررة','تسجيل دفعة مستحقة بعد التأكيد');save()}return made}
