function showLocalBackupToast(){if(!localBackupToastQuota())return;toast(window.LedgerBackup&&window.LedgerBackup.localBackupText?window.LedgerBackup.localBackupText():bkTxt(),2200)}function showRecurringPending(force,ruleId){var list=pendingRecurring().filter(function(x){return !ruleId||String(x.r.id)===String(ruleId)});if(!list.length||(!force&&!recPromptShown))return;if(!force&&!recurringPromptQuota())return;recPromptShown=true;var total=list.reduce(function(s,x){return s+x.a},0),seen={};list.forEach(function(x){seen[x.r.id]=x.r});var rules=Object.keys(seen).map(function(id){var r=seen[id],items=list.filter(function(x){return x.r.id==id}),sum_=items.reduce(function(s,x){return s+x.a},0);return '<li><b>'+esc(r.title)+'</b> — '+fmt(r.amount)+' '+esc(S.cur)+' لكل دفعة — '+esc(CATS[r.cat]||'')+(r.sub?' / '+esc(r.sub):'')+' — '+REC_FREQ[r.freq||'month']+' — من '+r.start+' إلى '+(r.end||'بدون نهاية')+' — '+items.length+' دفعة / '+fmt(sum_)+' '+esc(S.cur)+'</li>'}).join(''),dates=list.map(function(x){return '<li>'+esc(x.r.title)+(x.r.sub?' - '+esc(x.r.sub):'')+' — '+fmt(x.a)+' '+esc(S.cur)+' — '+x.d+' <button class=\"mini t-ok\" data-a=\"recOne\" data-r=\"'+x.r.id+'\" data-d=\"'+x.d+'\">تسجيل هذه الدفعة</button></li>'}).join(''),html='<b>سيتم تسجيل '+list.length+' مصروف مستقل بإجمالي '+fmt(total)+' '+esc(S.cur)+'</b><br><span class=\"hint\">تنبيه أثر رجعي: لن تُضاف أي دفعة قبل التأكيد الصريح.</span><p><b>ملخص القواعد</b></p><ul>'+rules+'</ul><p><b>تواريخ الدفعات</b></p><ul>'+dates+'</ul>';ask('مصاريف متكررة مستحقة للتسجيل',html,'تأكيد وتسجيل الكل الآن',function(){var n=confirmRecurringPending();done('تم تسجيل '+n+' مصروف متكرر بتاريخ الاستحقاق')},'تذكير لاحقًا')}

