function xcById(id){return (S.xc||[]).filter(function(c){return c.id==id})[0]}
function xcTitle(id){var c=xcById(id);return c?c.title:'دفعة استثنائية'}
function xreq(c,u){return c.req&&c.req[u.id]!=null?c.req[u.id]:(c.amount||0)}
function xpaid(c,u){return S.pay.filter(function(p){return p.k==='exc'&&p.x===c.id&&p.u===u.id}).reduce(function(s,p){return s+p.a},0)}
function xrest(c,u){return Math.max(0,xreq(c,u)-xpaid(c,u))}
function xstat(c,u){var q=xreq(c,u),p=xpaid(c,u);return q>0&&p>=q?['مدفوع','t-ok']:p>0?['جزئي','t-mid']:['غير مدفوع','t-no']}
function xtot(c){var r={req:0,col:0,spent:0,moved:0,bal:0};S.units.forEach(function(u){r.req+=xreq(c,u)});r.col=sum(S.pay.filter(function(p){return p.k==='exc'&&p.x===c.id}),'a');r.spent=sum(S.exp.filter(function(e){return e.x===c.id}),'a');r.moved=sum((S.xm||[]).filter(function(m){return m.c===c.id}),'a');r.bal=Math.round((r.col-r.spent-r.moved)*100)/100;return r}
