function xcCard(c){var t=xtot(c),pct=t.req?Math.min(100,t.col/t.req*100):0,op=c.status!=='closed';
  return '<button class="ucard xcc tapc" data-a="xcOpen" data-v="'+c.id+'"><div class="uh"><div><div class="un" style="font-size:18px">'+esc(c.title)+'</div><div class="us">'+c.date+'</div></div><span class="tag '+(op?'t-ok':'t-no')+'">'+(op?'مفتوح':'مغلق')+'</span></div><div class="us" style="margin-top:6px">'+esc(c.purpose)+'</div>'+
  '<div class="ug"><div><div class="l">المطلوب</div><b>'+fmt(t.req)+'</b></div><div><div class="l">المحصّل</div><b class="in">'+fmt(t.col)+'</b></div><div><div class="l">رصيد الدفعة</div><b class="'+(t.bal>0?'':'out')+'">'+fmt(t.bal)+'</b></div></div><div class="ubar"><i style="width:'+pct+'%"></i></div><div class="tapfoot"><span>اضغط لعرض التفاصيل وإدخال الدفعات والصرف والتعديل</span><i class="go">‹</i></div></button>'}
function vXc(){var L=(S.xc||[]).slice().sort(function(a,b){return a.date<b.date?1:-1}),T={col:0,spent:0,bal:0};L.forEach(function(c){var t=xtot(c);T.col+=t.col;T.spent+=t.spent;T.bal+=t.bal});
  return '<div class="top"><div><h1>الدفعات الاستثنائية</h1><small>إيرادات استثنائية لصرف عاجل غير دوري، منفصلة عن رصيد الصندوق</small></div><button class="btn s" data-a="addXc">+ طلب</button></div>'+segCv()+
  '<div class="tiles"><div class="tile t-in"><div class="l">المحصّل</div><div class="v">'+cnt(T.col)+'</div></div><div class="tile t-out"><div class="l">المصروف</div><div class="v">'+cnt(T.spent)+'</div></div><div class="tile t-bal"><div class="l">الرصيد المتاح</div><div class="v">'+cnt(T.bal)+'</div></div></div>'+
  '<div style="margin-top:14px">'+(L.length?L.map(xcCard).join(''):'<div class="empty">لا توجد طلبات استثنائية. اضغط على + طلب لإنشاء دفعة استثنائية مع وصف الغرض منها.</div>')+'</div>'}
function xcSection(){var L=(S.xc||[]).slice().sort(function(a,b){return a.date<b.date?1:-1});
  return '<div class="hrow"><h2>دفعات استثنائية</h2><button class="mini t-ok" data-a="addXc" style="margin-top:14px">+ طلب</button></div>'+(L.length?L.slice(0,3).map(xcCard).join('')+(L.length>3?'<button class="btn g" data-a="cvgo">عرض كل الدفعات الاستثنائية ('+L.length+')</button>':''):'<div class="card"><p class="hint" style="margin:0">لتحصيل مبالغ استثنائية من الملاك لصرف عاجل غير متكرر، مع وصف الغرض منها. تُحاسَب منفصلة عن الصندوق.</p></div>')}
