function repXc(c){var t=xtot(c),money=function(n){return fmt(n)+' '+S.cur},asc=function(a,b){return a.d<b.d?-1:1};
  return{file:'exceptional-'+c.id,title:'دفعة استثنائية: '+c.title,summary:[['الغرض',c.purpose.length>70?c.purpose.slice(0,70)+'…':c.purpose],['تاريخ الطلب',c.date],['الحالة',c.status==='closed'?'مغلق':'مفتوح'],['إجمالي المطلوب',money(t.req)],['إجمالي المحصّل',money(t.col)],['إجمالي المصروف منها',money(t.spent)],['المرحّل إلى الصندوق',money(t.moved)],['رصيد الدفعة المتاح',money(t.bal)]],
    tables:[{title:'حالة الوحدات',head:['الوحدة','المالك','المطلوب','المدفوع','المتبقي','الحالة'],rows:S.units.map(function(u){return[u.name,u.owner||'-',fmt(xreq(c,u)),fmt(xpaid(c,u)),fmt(xrest(c,u)),xstat(c,u)[0]]})},
      {title:'الدفعات المحصّلة',head:['التاريخ','الوحدة','المبلغ','البيان'],rows:S.pay.filter(function(p){return p.k==='exc'&&p.x===c.id}).sort(asc).map(function(p){return[p.d,(unit(p.u)||{}).name||'-',fmt(p.a),p.n||'-']})},
      {title:'المصروفات من الدفعة',head:['التاريخ','البند','التصنيف','المبلغ'],rows:S.exp.filter(function(e){return e.x===c.id}).sort(asc).map(function(e){return[e.d,e.t,catShort(e),fmt(e.a)]})},
      {title:'الترحيل إلى الصندوق',head:['التاريخ','البيان','المبلغ'],rows:(S.xm||[]).filter(function(m){return m.c===c.id}).sort(asc).map(function(m){return[m.d,m.n||'-',fmt(m.a)]})}]}}
var fmt2=function(n){return (Math.round((n||0)*100)/100).toLocaleString('en-US',{minimumFractionDigits:2,maximumFractionDigits:2})};
var M2=function(n){return fmt2(n)+' '+S.cur};
function xfSum(){return sum((S.dl||[]).filter(function(x){return x.t==='xfer'}),'a')}
function accSum(){return sum((S.dl||[]).filter(function(x){return x.t==='acc'}),'a')}
function adjSum(){return sum((S.dl||[]).filter(function(x){return x.t==='adj'}),'a')}
function pend(){return Math.round((accSum()-xfSum()-adjSum())*100)/100}
function dpById(id){return (S.deps||[]).filter(function(d){return d.id==id})[0]}
function dpName(id){var d=dpById(id);return d?d.name:'وديعة'}
function dpSum(id,t){return sum((S.dl||[]).filter(function(x){return x.dp===id&&x.t===t}),'a')}
function pendOf(id){return Math.round((dpSum(id,'acc')-dpSum(id,'xfer')-dpSum(id,'adj'))*100)/100}
function migDeps(){if(!S.deps)S.deps=[];var ch=false;if(S.dep&&!S.deps.length){var id=S.n++;S.deps.push({id:id,name:'الوديعة الأولى',amount:S.dep.amount||0,rate:S.dep.rate||0,start:S.dep.start||'',status:'open'});S.dep=null;ch=true}
  if(S.deps.length)(S.dl||[]).forEach(function(x){if(x.dp==null){x.dp=S.deps[0].id;ch=true}});return ch}
function accrue(){var cm=today().slice(0,7),ch=false;if(!S.dl)S.dl=[];
  (S.deps||[]).forEach(function(d){if(d.status==='closed'||!(d.rate>0)||!(d.amount>0)||!d.start)return;
    for(var m=d.start;m<=cm;m=shift(m,1)){if(S.dl.some(function(x){return x.t==='acc'&&x.dp===d.id&&x.m===m}))continue;S.dl.push({id:S.n++,t:'acc',dp:d.id,m:m,d:m+'-01',a:Math.round(d.amount*d.rate)/100,n:'وديعة '+fmt(d.amount)+' × '+d.rate+'%'});ch=true}});
  if(ch){lg('احتساب فائدة الوديعة','حتى '+cm);save()}return ch}
