function layout(rep){var pages=[[]],used=0;function cap(){return pages.length===1?23:28}function np(){pages.push([]);used=0}function add(it,c){if(used+c>cap())np();pages[pages.length-1].push(it);used+=c}
  rep.summary.forEach(function(r){add({k:'sum',c:r},1)});
  rep.tables.forEach(function(t){if(used+5>cap())np();add({k:'title',c:t.title},2);var cols=t.head.map(function(x){return htone(x,/مصروف/.test(t.title))}),h={k:'head',c:t.head,cols:cols};add(h,1);(t.rows.length?t.rows:[t.head.map(function(x,i){return i===0?'لا توجد بيانات':'-'})]).forEach(function(r){if(used+1>cap()){np();pages[pages.length-1].push(h);used+=1}add({k:'row',c:r,cols:cols},1)})});return pages}
